//! lapid-c: the engine-level C API of lapid (`include/lapid.h`, generated by cbindgen).
//!
//! Everything exported here is `extern "C"` with plain C types: opaque refcounted handles
//! (`lapid_device`, `lapid_file`, `lapid_tensor`), `int32_t` codes for dtypes and ops, and
//! an `int32_t` status as the return value of every fallible function. Error details are a
//! thread-local JSON string (`lapid_last_error`). Panics never cross the boundary.
//!
//! Regenerate the header with `tools/check_c_header.sh --write`.

#![allow(clippy::missing_safety_doc)] // the safety contract is documented once, in the header

mod device;
mod error;
mod file;
mod handle;
mod ops;
mod ops_nn;
mod tensor;
#[cfg(test)]
mod tests;

pub use device::*;
pub use error::*;
pub use file::*;
pub use handle::{LapidDevice, LapidFile, LapidTensor};
pub use ops::*;
pub use ops_nn::*;
pub use tensor::*;

use std::ffi::c_char;

/// ABI version of this header and library. Bumped on any incompatible change to a
/// signature, struct or constant. Pass it to `lapid_check_abi` at startup.
pub const LAPID_ABI_VERSION: u32 = 1;

/// Element type code (`LAPID_DTYPE_*`).
pub type LapidDType = i32;
pub const LAPID_DTYPE_F32: LapidDType = 0;
pub const LAPID_DTYPE_F16: LapidDType = 1;
pub const LAPID_DTYPE_BF16: LapidDType = 2;
pub const LAPID_DTYPE_I32: LapidDType = 3;
/// 8-bit symmetric ints, groups of 32 along a row, f16 scale (2-D/3-D weights only).
pub const LAPID_DTYPE_INT8: LapidDType = 4;
/// 4-bit ints, groups of 32 along a row, f16 scale (2-D/3-D weights only).
pub const LAPID_DTYPE_INT4: LapidDType = 5;
/// ggml Q4_K super-blocks (2-D/3-D weights only, like all quantized dtypes).
pub const LAPID_DTYPE_Q4_K: LapidDType = 6;
/// ggml Q5_K super-blocks.
pub const LAPID_DTYPE_Q5_K: LapidDType = 7;
/// ggml Q6_K super-blocks.
pub const LAPID_DTYPE_Q6_K: LapidDType = 8;
pub const LAPID_DTYPE_MXFP4: LapidDType = 9;
/// ggml IQ2_XXS super-blocks (2.06 bpw).
pub const LAPID_DTYPE_IQ2_XXS: LapidDType = 10;
/// ggml IQ2_S super-blocks (2.56 bpw).
pub const LAPID_DTYPE_IQ2_S: LapidDType = 11;
/// ggml IQ3_XXS super-blocks (3.06 bpw).
pub const LAPID_DTYPE_IQ3_XXS: LapidDType = 12;

/// Unary op code for `lapid_unary` (`LAPID_UNARY_*`).
pub type LapidUnaryOp = i32;
pub const LAPID_UNARY_NEG: LapidUnaryOp = 0;
pub const LAPID_UNARY_EXP: LapidUnaryOp = 1;
pub const LAPID_UNARY_LOG: LapidUnaryOp = 2;
pub const LAPID_UNARY_SQRT: LapidUnaryOp = 3;
pub const LAPID_UNARY_RSQRT: LapidUnaryOp = 4;
pub const LAPID_UNARY_RECIP: LapidUnaryOp = 5;
pub const LAPID_UNARY_SIN: LapidUnaryOp = 6;
pub const LAPID_UNARY_COS: LapidUnaryOp = 7;
pub const LAPID_UNARY_TANH: LapidUnaryOp = 8;
pub const LAPID_UNARY_ERF: LapidUnaryOp = 9;
pub const LAPID_UNARY_ABS: LapidUnaryOp = 10;

/// Binary op code for `lapid_binary` / `lapid_binary_scalar` (`LAPID_BINARY_*`).
pub type LapidBinaryOp = i32;
pub const LAPID_BINARY_ADD: LapidBinaryOp = 0;
pub const LAPID_BINARY_SUB: LapidBinaryOp = 1;
pub const LAPID_BINARY_MUL: LapidBinaryOp = 2;
pub const LAPID_BINARY_DIV: LapidBinaryOp = 3;
pub const LAPID_BINARY_MAX: LapidBinaryOp = 4;
pub const LAPID_BINARY_MIN: LapidBinaryOp = 5;
pub const LAPID_BINARY_POW: LapidBinaryOp = 6;
/// a < b as 0/1 in the operand dtype.
pub const LAPID_BINARY_CMP_LT: LapidBinaryOp = 7;
/// a == b as 0/1 in the operand dtype.
pub const LAPID_BINARY_CMP_EQ: LapidBinaryOp = 8;
/// Truncated remainder; REM through SHR are integer ops (i32 only).
pub const LAPID_BINARY_REM: LapidBinaryOp = 9;
pub const LAPID_BINARY_BITAND: LapidBinaryOp = 10;
pub const LAPID_BINARY_BITOR: LapidBinaryOp = 11;
pub const LAPID_BINARY_BITXOR: LapidBinaryOp = 12;
pub const LAPID_BINARY_SHL: LapidBinaryOp = 13;
pub const LAPID_BINARY_SHR: LapidBinaryOp = 14;

/// Reduction op code for `lapid_reduce` (`LAPID_REDUCE_*`).
pub type LapidReduceOp = i32;
pub const LAPID_REDUCE_SUM: LapidReduceOp = 0;
pub const LAPID_REDUCE_MAX: LapidReduceOp = 1;

/// Library version, e.g. "0.1.0". Static string, never free it.
#[unsafe(no_mangle)]
pub extern "C" fn lapid_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}

/// ABI version of the loaded library (compare with `LAPID_ABI_VERSION`).
#[unsafe(no_mangle)]
pub extern "C" fn lapid_abi_version() -> u32 {
    LAPID_ABI_VERSION
}

/// `LAPID_OK` when the loaded library implements `header_abi` (pass `LAPID_ABI_VERSION`),
/// else `LAPID_ERR_ABI_MISMATCH` with details in `lapid_last_error`.
#[unsafe(no_mangle)]
pub extern "C" fn lapid_check_abi(header_abi: u32) -> LapidStatus {
    error::guard(|| {
        if header_abi != LAPID_ABI_VERSION {
            return Err(engine::Error::new(
                "abi_mismatch",
                format!("header ABI {header_abi}, library ABI {LAPID_ABI_VERSION} (lapid {})", env!("CARGO_PKG_VERSION")),
            ));
        }
        Ok(())
    })
}

pub(crate) fn dtype_from_c(d: LapidDType) -> engine::Result<engine::DType> {
    use engine::DType;
    Ok(match d {
        LAPID_DTYPE_F32 => DType::F32,
        LAPID_DTYPE_F16 => DType::F16,
        LAPID_DTYPE_BF16 => DType::BF16,
        LAPID_DTYPE_I32 => DType::I32,
        LAPID_DTYPE_INT8 => DType::Int8,
        LAPID_DTYPE_INT4 => DType::Int4,
        LAPID_DTYPE_Q4_K => DType::Q4K,
        LAPID_DTYPE_Q5_K => DType::Q5K,
        LAPID_DTYPE_Q6_K => DType::Q6K,
        LAPID_DTYPE_MXFP4 => DType::Mxfp4,
        LAPID_DTYPE_IQ2_XXS => DType::Iq2Xxs,
        LAPID_DTYPE_IQ2_S => DType::Iq2S,
        LAPID_DTYPE_IQ3_XXS => DType::Iq3Xxs,
        other => return Err(engine::Error::new("invalid_argument", format!("unknown dtype code {other}"))),
    })
}

pub(crate) fn dtype_to_c(d: engine::DType) -> LapidDType {
    use engine::DType;
    match d {
        DType::F32 => LAPID_DTYPE_F32,
        DType::F16 => LAPID_DTYPE_F16,
        DType::BF16 => LAPID_DTYPE_BF16,
        DType::I32 => LAPID_DTYPE_I32,
        DType::Int8 => LAPID_DTYPE_INT8,
        DType::Int4 => LAPID_DTYPE_INT4,
        DType::Q4K => LAPID_DTYPE_Q4_K,
        DType::Q5K => LAPID_DTYPE_Q5_K,
        DType::Q6K => LAPID_DTYPE_Q6_K,
        DType::Mxfp4 => LAPID_DTYPE_MXFP4,
        DType::Iq2Xxs => LAPID_DTYPE_IQ2_XXS,
        DType::Iq2S => LAPID_DTYPE_IQ2_S,
        DType::Iq3Xxs => LAPID_DTYPE_IQ3_XXS,
    }
}
